// Item 22c: the pinned X-13 deterministic-effect allocation staging of the
// X13Kernel (pinned rjd3 3.9.0 jars) — the fixed-coefficient preadjust
// (initialStep) and the finals restore — qualified bit-exactly against the
// x13-allocation fixture corpus (validation/evidence/native/x13-allocation,
// captured through X13Kernel.of(spec, ctx).process on fully specified
// fixed-coefficient models), embedded verbatim at 17 significant digits.
// Every case records the pinned input, the model variables in pinned
// model-description order (class, EXACT regeffect bucket, coefficients as
// given to the pinned run and regression columns), the stored a-tables and
// out, the captured X11 D10..D13/C17 of the same run and the finals tables.
// Each case is verified three ways: the native preadjust against the stored
// a-tables and out at exact equality; the native X-11 selection pass over
// the preadjusted series against the captured D10..D13/C17 (at exact
// equality, or, under log-additive, across the pinned results-builder stage
// (exp plus the default ratio bias correction) at transcendental tolerance);
// and the native restore against the captured finals both over the captured
// X-11 tables (exact) and over the native selection-pass tables (end-to-end
// wiring). The pinned mode-forcing rule
// (non-log -> Additive, log -> Multiplicative unless LogAdditive or
// PseudoAdditive is requested) is re-asserted from the case metadata. The
// corpus covers the additive, forced-additive, multiplicative (log model),
// log-additive and pseudo-additive finals, the quarterly and monthly
// frequencies, the empty model (all-zero buckets) and the outlier outside
// the three outlier buckets (contributes to no table).
#include "kalos/x13_allocation.hpp"
#include "kalos/x11_selection_pass.hpp"
#include "kalos/parallel.hpp"
#include <algorithm>
#include <cassert>
#include <cmath>
#include <cstdlib>
#include <iostream>
#include <stdexcept>
#include <string>
